import heapq

def match(orders):
    trades = []

    buy_heap = []  # (-price, seq, id)
    sell_heap = []  # (price, seq, id)

    orders_state = {}  # id -> dict with side, price, qty, active

    seq_counter = 0

    def add_order(oid, side, price, qty):
        nonlocal seq_counter
        orders_state[oid] = {'side': side, 'price': price, 'qty': qty, 'active': True}
        seq = seq_counter
        seq_counter += 1
        if side == 'buy':
            heapq.heappush(buy_heap, (-price, seq, oid))
        else:
            heapq.heappush(sell_heap, (price, seq, oid))

    def peek_best_buy():
        while buy_heap:
            negprice, seq, oid = buy_heap[0]
            st = orders_state.get(oid)
            if st is None or not st['active'] or st['qty'] <= 0:
                heapq.heappop(buy_heap)
                continue
            return oid, -negprice
        return None, None

    def peek_best_sell():
        while sell_heap:
            price, seq, oid = sell_heap[0]
            st = orders_state.get(oid)
            if st is None or not st['active'] or st['qty'] <= 0:
                heapq.heappop(sell_heap)
                continue
            return oid, price
        return None, None

    def pop_best_buy():
        while buy_heap:
            negprice, seq, oid = heapq.heappop(buy_heap)
            st = orders_state.get(oid)
            if st is None or not st['active'] or st['qty'] <= 0:
                continue
            return oid, -negprice
        return None, None

    def pop_best_sell():
        while sell_heap:
            price, seq, oid = heapq.heappop(sell_heap)
            st = orders_state.get(oid)
            if st is None or not st['active'] or st['qty'] <= 0:
                continue
            return oid, price
        return None, None

    for order in orders:
        otype = order[0]

        if otype == 'cancel':
            oid = order[1]
            st = orders_state.get(oid)
            if st is not None and st['active'] and st['qty'] > 0:
                st['active'] = False
            continue

        oid = order[1]
        side = order[2]

        if otype == 'market':
            qty = order[3]
            price = None
        else:
            price = order[3]
            qty = order[4]

        orders_state[oid] = {'side': side, 'price': price, 'qty': qty, 'active': True}

        remaining = qty

        if side == 'buy':
            while remaining > 0:
                sell_oid, sell_price = peek_best_sell()
                if sell_oid is None:
                    break
                if price is not None and sell_price > price:
                    break
                sell_st = orders_state[sell_oid]
                trade_qty = min(remaining, sell_st['qty'])
                trades.append([oid, sell_oid, sell_price, trade_qty])
                remaining -= trade_qty
                sell_st['qty'] -= trade_qty
                if sell_st['qty'] <= 0:
                    sell_st['active'] = False
                    pop_best_sell()
            orders_state[oid]['qty'] = remaining
            if otype == 'limit' and remaining > 0:
                add_order(oid, side, price, remaining)
            else:
                orders_state[oid]['active'] = False

        else:  # sell
            while remaining > 0:
                buy_oid, buy_price = peek_best_buy()
                if buy_oid is None:
                    break
                if price is not None and buy_price < price:
                    break
                buy_st = orders_state[buy_oid]
                trade_qty = min(remaining, buy_st['qty'])
                trades.append([buy_oid, oid, buy_price, trade_qty])
                remaining -= trade_qty
                buy_st['qty'] -= trade_qty
                if buy_st['qty'] <= 0:
                    buy_st['active'] = False
                    pop_best_buy()
            orders_state[oid]['qty'] = remaining
            if otype == 'limit' and remaining > 0:
                add_order(oid, side, price, remaining)
            else:
                orders_state[oid]['active'] = False

    return trades

